return {h=12,w=280,cr=45,hc=20,bh=70,gr="medium",eg={"water1","flying"},st={60,50,100,95,70,65},ab={{51,0},{2,0},{44,1}},genus={en="Water Bird Pokémon",es="Pokémon Ave Agua",pt="Pokémon Ave Aquática"},flavor={en={[7]="PELIPPER is a flying transporter that carries small Pokémon and eggs inside its massive bill. This Pokémon builds its nest on steep cliffs facing the sea.",[8]="PELIPPER searches for food while in flight by skimming the wave tops. This Pokémon dips its large bill in the sea to scoop up food, then swallows everything in one big gulp.",[9]="It skims the tops of waves as it flies. When it spots prey, it uses its large beak to scoop up the victim with water. It protects its eggs in its beak.",[10]="It is a flying transporter that carries small Pokémon in its beak. It bobs on the waves to rest its wings.",[11]="It is a flying transporter that carries small Pokémon in its beak. It bobs on the waves to rest its wings.",[12]="It dips its large bill in the sea, then scoops up numerous prey along with water.",[13]="It acts as a delivery service by carrying small Pokémon in its bill. It bobs on the waves to rest.",[14]="It is a messenger of the skies, carrying small Pokémon and eggs to safety in its bill.",[15]="It protects its young in its beak. It bobs on waves, resting on them on days when the waters are calm.",[16]="It protects its young in its beak. It bobs on waves, resting on them on days when the waters are calm.",[17]="It is a messenger of the skies, carrying small Pokémon and eggs to safety in its bill.",[18]="It is a messenger of the skies, carrying small Pokémon and eggs to safety in its bill.",[21]="Skimming the water’s surface, it dips its large bill in the sea, scoops up food and water, and carries it.",[22]="Skimming the water’s surface, it dips its large bill in the sea, scoops up food and water, and carries it.",[23]="It dips its large bill in the sea, then scoops up numerous prey along with water.",[24]="It is a messenger of the skies, carrying small Pokémon and eggs to safety in its bill.",[25]="Pelipper is a flying transporter that carries small Pokémon and eggs inside its massive bill. This Pokémon builds its nest on steep cliffs facing the sea.",[26]="Pelipper searches for food while in flight by skimming the wave tops. This Pokémon dips its large bill in the sea to scoop up food, then swallows everything in one big gulp.",[27]="Its spacious beak is large enough for a small child to fit right inside.",[28]="Gathering food is the work of young males. They store food in their capacious beaks and carry it back to others waiting in the nest.",[29]="It places small Pokémon into its spacious beak and carries them around. No one knows where it’s taking them.",[30]="It scoops up Wishiwashi in its huge beak and swallows them whole. It can devour more than 30 at one go!",[33]="It is a messenger of the skies, carrying small Pokémon and eggs to safety in its bill.",[34]="Skimming the water’s surface, it dips its large bill in the sea, scoops up food and water, and carries it."},es={[23]="Hunde su gran pico en el mar para sacar numerosas presas junto con mucha agua.",[24]="Transporta a pequeños Pokémon y Huevos en su pico hasta lugares seguros.",[25]="Pelipper vuela transportando pequeños huevos y Pokémon dentro del descomunal pico que tiene. Este Pokémon construye su nido en escarpados acantilados frente al mar.",[26]="Pelipper busca su comida mientras vuela y esquiva las crestas de las olas. Cuando localiza una presa, sumerge el largo pico en el agua para pescarla y se la traga de una vez.",[27]="Su pico es tan grande que podría acomodar a un niño pequeño sin ningún problema.",[28]="Los machos jóvenes se encargan de reunir comida. La acumulan en sus grandes picos para luego llevarla a sus compañeros en los nidos.",[29]="Transporta Pokémon pequeños en su enorme pico, aunque nadie sabe a dónde los lleva.",[30]="Atrapa Wishiwashi con su enorme pico para luego engullirlos enteros, llegando a comer más de 30 ejemplares de una sentada.",[33]="Transporta a pequeños Pokémon y Huevos en su pico hasta lugares seguros.",[34]="Vuela a ras de la superficie marina para llenar su inmenso pico de agua y comida, que se lleva consigo."},pt="Rente à superfície da água, mergulha o bico grande no mar, recolhe comida e água e as transporta."},evo={{s=278},{s=279,from=278,c={{t="level-up",lv=25}}}},moves={[5]={1,45,1,55,1,346,1,17,3,55,7,48,13,17,21,54,25,182,33,254,33,256,47,255,61,56},[6]={1,45,1,55,1,346,1,17,3,55,7,48,13,17,21,54,25,182,33,254,33,256,47,255,61,56},[7]={1,45,1,55,1,346,1,17,3,55,7,48,13,17,21,54,25,182,33,254,33,256,47,255,61,56},[8]={1,45,1,55,1,346,1,17,6,48,11,17,16,54,19,352,24,371,25,182,31,355,38,254,38,256,38,255,43,374,50,366,57,56},[9]={1,45,1,55,1,346,1,17,6,48,11,17,16,54,19,352,24,371,25,182,31,355,38,254,38,256,38,255,43,374,50,366,57,56},[10]={1,45,1,55,1,346,1,17,6,48,11,17,16,54,19,352,24,371,25,182,31,355,38,254,38,256,38,255,43,374,50,366,57,56},[11]={1,487,1,45,1,55,1,346,1,17,6,48,11,17,16,54,19,352,24,371,25,182,31,355,38,254,38,256,38,255,43,374,50,366,57,56,63,542},[12]={1,45,1,55,1,346,1,17,3,55,7,48,13,17,21,54,25,182,33,254,33,256,47,255,61,56},[13]={1,45,1,55,1,346,1,17,3,55,7,48,13,17,21,54,25,182,33,254,33,256,47,255,61,56},[14]={1,487,1,45,1,55,1,346,1,17,6,48,9,17,14,54,17,352,22,371,25,182,28,355,34,362,39,254,39,256,39,255,46,374,52,366,58,56,63,542},[15]={1,56,1,366,1,487,1,45,1,55,1,346,1,17,6,48,9,17,14,54,17,352,22,371,25,182,28,355,34,362,39,254,39,256,39,255,46,374,52,366,58,56,63,542},[16]={1,542,1,56,1,366,1,487,1,45,1,55,1,346,1,17,5,48,8,17,12,54,15,352,19,371,22,355,25,182,28,362,33,254,33,256,33,255,39,374,44,366,50,56,55,542},[17]={0,182,1,182,1,542,1,56,1,366,1,487,1,45,1,55,1,346,1,17,5,48,8,17,12,54,15,352,19,371,22,362,28,374,33,254,33,256,33,255,39,355,44,366,50,56,55,542},[18]={0,182,1,182,1,542,1,56,1,366,1,487,1,45,1,55,1,346,1,17,5,48,8,17,12,54,15,352,19,371,22,362,28,374,33,254,33,256,33,255,39,355,44,366,50,56,55,542},